droid.webkit.WebView\nimport android.webkit.WebSettings\nimport android.widget.*\nimport androidx.appcompat.app.AppCompatActivity\nimport androidx.recyclerview.widget.GridLayoutManager\nimport androidx.recyclerview.widget.RecyclerView\n\nclass MainActivity : AppCompatActivity() {\n\n    private lateinit var webView: WebView\n    private lateinit var tabPreviewOverlay: View\n    private lateinit var tabRecycler: RecyclerView\n    private lateinit var vpnButton: TextView\n    private lateinit var adBlockButton: ImageView\n\n    override fun onCreate(savedInstanceState: Bundle?) {\n        super.onCreate(savedInstanceState)\n        setContentView(R.layout.activity_main)\n\n        webView = findViewById(R.id.webView)\n        tabPreviewOverlay = findViewById(R.id.tabPreviewOverlay)\n        tabRecycler = findViewById(R.id.tabRecycler)\n        vpnButton = findViewById(R.id.vpnButton)\n        adBlockButton = findViewById(R.id.adBlockButton)\n\n        setupWebView()\n        setupTabs()\n        setupVpn()\n        setupAdBlock()\n\n        if (TabManager.tabs.isEmpty()) {\n            TabManager.createNewTab()\n        }\n        loadHome()\n    }\n\n    private fun setupWebView() {\n        webView.settings.apply {\n            javaScriptEnabled = true\n            domStorageEnabled = true\n            cacheMode = WebSettings.LOAD_DEFAULT\n            // Gizlilik sekmesi için ayrı ayar\n        }\n        webView.webViewClient = BrowserWebViewClient { preview -\u003e\n            // Önizleme güncellendi\n        }\n    }\n\n    private fun setupTabs() {\n        tabRecycler.layoutManager = GridLayoutManager(this, 2)\n        tabRecycler.adapter = TabPreviewAdapter(TabManager.tabs,\n            onTabClick = { tab -\u003e\n                TabManager.currentTabId = tab.id\n                tabPreviewOverlay.visibility = View.GONE\n                webView.loadUrl(tab.url.ifEmpty { \"https://www.google.com\" })\n                if (tab.isPrivate) {\n                    webView.clearHistory()\n                    // Gizlilik modu UI\n                }\n            },\n            onTabClose = { tab -\u003e\n                TabManager.tabs.remove(tab)\n                tabRecycler.adapter?.notifyDataSetChanged()\n                if (TabManager.tabs.isEmpty()) TabManager.createNewTab()\n            }\n        )\n\n        findViewById\u003cView\u003e(R.id.tabCountButton).setOnClickListener {\n            // ÖNİZLEME AÇ - İSTEDİĞİN ÖZELLİK BURASI\n            TabManager.getCurrentTab()?.let {\n                val bmp = TabManager.capturePreview(webView)\n                TabManager.updatePreview(it.id, bmp)\n            }\n            tabRecycler.adapter?.notifyDataSetChanged()\n            tabPreviewOverlay.visibility = View.VISIBLE\n        }\n\n        findViewById\u003cView\u003e(R.id.newTabButton).setOnClickListener {\n            TabManager.createNewTab()\n            tabRecycler.adapter?.notifyDataSetChanged()\n            loadHome()\n            tabPreviewOverlay.visibility = View.GONE\n        }\n\n        findViewById\u003cView\u003e(R.id.newPrivateTabButton).setOnClickListener {\n            TabManager.createNewTab(isPrivate = true)\n            tabRecycler.adapter?.notifyDataSetChanged()\n            Toast.makeText(this, \"Gizlilik sekmesi açıldı - Geçmiş kaydedilmiyor\", Toast.LENGTH_SHORT).show()\n            loadHome()\n            tabPreviewOverlay.visibility = View.GONE\n        }\n    }\n\n    private fun setupVpn() {\n        updateVpnUi()\n        vpnButton.setOnClickListener {\n            // VPN Seçici Dialog\n            val locations = SmartProxyManager.Location.values()\n            val names = locations.map { it.displayName }.toTypedArray()\n            android.app.AlertDialog.Builder(this)\n                .setTitle(\"Smart VPN - Konum Seç\")\n                .setItems(names) { _, which -\u003e\n                    val loc = locations[which]\n                    SmartProxyManager.setProxy(this, webView, loc)\n                    updateVpnUi()\n                    Toast.makeText(this, \"${loc.displayName} seçildi, Google dahil her site açılır\", Toast.LENGTH_SHORT).show()\n                    webView.reload()\n                }.show()\n        }\n    }\n\n    private fun updateVpnUi() {\n        vpnButton.text = SmartProxyManager.getStatusText()\n        vpnButton.setBackgroundResource(\n            if (SmartProxyManager.isVpnActive) R.drawable.bg_vpn_active else R.drawable.bg_vpn_inactive\n        )\n    }\n\n    private fun setupAdBlock() {\n        adBlockButton.setOnClickListener {\n            AdBlocker.isEnabled = !AdBlocker.isEnabled\n            Toast.makeText(this, if (AdBlocker.isEnabled) \"Reklam engelleme aktif\" else \"Reklam engelleme kapalı\", Toast.LENGTH_SHORT).show()\n            webView.reload()\n        }\n    }\n\n    private fun loadHome() {\n        webView.loadUrl(\"https://www.google.com\")\n    }\n}\n11:T824c,\u003cpre class=\"shiki shiki-themes github-light github-dark\" style=\"--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e\" tabindex=\"0\"\u003e\u003ccode\u003e\u003cspan class=\"line\"\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003epackage\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F42C1;--shiki-dark:#B392F0\"\u003e com.pusula.browser\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003eimport\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F42C1;--shiki-dark:#B392F0\"\u003e android.os.Bundle\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"line\"\u003e\u003cspan style=\"--shiki-light:#D73A49;--shiki-dark:#F97583\"\u003eimport\u003c/span\u003e\u003cspan style=\"--shiki-light:#6F42C1;--shiki-dark:#B392F0\"\u003e android.view.View\u003c/span\u003e\u003c/span\u003e\n\u003cspan class=\"l